declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_access();
$perpusWaktu=perpus_waktu_pembelajaran_aktif($pdo);
$q=trim((string)($_GET['q']??''));$kelasId=(int)($_GET['kelas_id']??0);$where=['DATE(k.waktu_kunjungan)=CURDATE()'];$params=[];
if($q!==''){$where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($kelasId>0){$where[]='k.kelas_id=?';$params[]=$kelasId;}
$sql="SELECT k.id,k.waktu_kunjungan,k.metode,s.nama,s.nis,s.nisn,COALESCE(mk.nama,'-') kelas,COALESCE(u.nama,'-') petugas FROM perpustakaan_kunjungan k JOIN siswa s ON s.id=k.siswa_id LEFT JOIN master_kelas mk ON mk.id=k.kelas_id LEFT JOIN users u ON u.id=k.petugas_id WHERE ".implode(' AND ',$where)." ORDER BY k.id DESC LIMIT 200";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$kelasRows=$pdo->query("SELECT mk.id,mk.nama FROM siswa_kelas sk JOIN master_kelas mk ON mk.id=sk.kelas_id JOIN tahun_pelajaran tp ON tp.id=sk.tahun_pelajaran_id WHERE sk.status='aktif' AND tp.aktif=1 GROUP BY mk.id,mk.nama ORDER BY mk.nama")->fetchAll();$today=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_kunjungan WHERE DATE(waktu_kunjungan)=CURDATE()")->fetchColumn();$csrf=csrf_token();$page_title='Pengunjung Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
