const soundCtl=SPLASMA_SCANNER_SOUND.bind("soundToggle");
const BASE=<?=json_encode(BASE_URL)?>,CSRF=<?=json_encode($csrf)?>,$=id=>document.getElementById(id);
function renderRecent(rows){const body=$('recentVisitsBody');if(!body)return;body.innerHTML=rows.length?rows.map(r=>'<tr><td>'+esc(r.waktu_kunjungan)+'</td><td><strong>'+esc(r.nama)+'</strong><div class="muted">'+esc(r.nis||'')+'</div></td><td>'+esc(r.kelas)+'</td><td><span class="badge bg-secondary">'+esc((r.metode||'').charAt(0).toUpperCase()+(r.metode||'').slice(1))+'</span></td><td>'+esc(r.petugas)+'</td></tr>').join(''):'<tr><td colspan="5" class="empty-state">Belum ada kunjungan hari ini.</td></tr>'}
async function refreshRecent(){const u=BASE+'perpustakaan/pengunjung_api.php?action=recent&kelas_id='+encodeURIComponent($('kelasManual').value||'')+'&q='+encodeURIComponent(new URLSearchParams(location.search).get('q')||'');const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();if(!d.ok)return;renderRecent(d.data||[]);$('todayCount').textContent=Number(d.today||0).toLocaleString('id-ID')}
if(window.SPLASMA_REALTIME){SPLASMA_REALTIME.register('perpus-pengunjung-recent',refreshRecent,5000);SPLASMA_REALTIME.start('perpus-pengunjung-recent')}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function msg(t,type='success'){$('msg').innerHTML='<div class="alert '+(type==='error'?'alert-danger':'alert-success')+'">'+t+'</div>';setTimeout(()=>{$('msg').innerHTML=''},5000)}
async function record(qr,metode){qr=(qr||'').trim();if(!qr)return;const fd=new URLSearchParams({action:'scan',kode_qr:qr,metode,csrf_token:CSRF});try{const r=await fetch(BASE+'perpustakaan/pengunjung_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:fd,cache:'no-store'}),d=await r.json();if(d.ok){SPLASMA_SCANNER_SOUND.beep(true);msg('<strong>'+esc(d.nama)+'</strong> · '+esc(d.kelas)+'<br>Kunjungan berhasil dicatat pada '+esc(d.waktu)+' WIB.');$('usb').value='';$('search').value='';$('results').innerHTML='';$('selected').style.display='none';refreshRecent().catch(()=>{});}else if(d.duplicate){SPLASMA_SCANNER_SOUND.beep(false);msg('<strong>'+esc(d.nama)+'</strong><br>Sudah tercatat sebagai pengunjung hari ini.<br><span class="muted">Kunjungan pertama: '+esc(d.waktu)+' WIB.</span>','error');}else {SPLASMA_SCANNER_SOUND.beep(false);msg(esc(d.message||'Gagal mencatat kunjungan.'),'error')}}catch(e){msg('Tidak dapat terhubung ke server.','error')}}
async function lookup(){const q=$('search').value.trim(),kelas=$('kelasManual').value;if(q.length<2){$('results').innerHTML='';return}const u=BASE+'perpustakaan/pengunjung_api.php?action=lookup&q='+encodeURIComponent(q)+(kelas?'&kelas_id='+encodeURIComponent(kelas):'');try{const r=await fetch(u,{cache:'no-store'}),d=await r.json();$('results').innerHTML=(d.data||[]).map(s=>'<button type="button" class="student-result" data-qr="'+esc(s.kode_qr)+'"><strong>'+esc(s.nama)+'</strong><div class="muted">'+esc(s.nis)+' · '+esc(s.nisn)+' · '+esc(s.kelas)+'</div></button>').join('')||'<div class="p-3 muted">Siswa tidak ditemukan.</div>';document.querySelectorAll('.student-result').forEach(b=>b.onclick=()=>{const s=d.data.find(x=>x.kode_qr===b.dataset.qr);$('selected').style.display='block';$('selected').innerHTML='<strong>'+esc(s.nama)+'</strong><div class="muted">'+esc(s.nis)+' · '+esc(s.kelas)+'</div><button type="button" class="btn btn-primary btn-sm mt-2" onclick="record('+JSON.stringify(s.kode_qr)+',\'manual\')">Catat Kunjungan</button>';$('results').innerHTML=''})}catch(e){$('results').innerHTML='<div class="p-3 text-danger">Pencarian gagal.</div>'}}
let st;function scheduleLookup(){clearTimeout(st);st=setTimeout(lookup,180)}$('search').addEventListener('input',scheduleLookup);$('kelasManual').addEventListener('change',()=>{if($('search').value.trim().length>=2)lookup()});$('saveUsb').onclick=()=>record($('usb').value,'usb');$('usb').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();record($('usb').value,'usb')}});
// USB HID scanner: tangkap burst keyboard agar scan tetap diproses walaupun fokus tidak berada di kolom USB.
let usbBuffer='',usbTimer=null,usbLastAt=0;const USB_BURST_MAX_GAP=90,USB_FLUSH_DELAY=180;
function clearUsbBuffer(){usbBuffer='';if(usbTimer){clearTimeout(usbTimer);usbTimer=null}}
function processUsbBuffer(){const code=usbBuffer.trim();clearUsbBuffer();if(code){$('usb').value=code;record(code,'usb')}}
function captureUsbKey(e){const target=e.target;if(target===$('usb'))return;if(target&&(target.matches?.('input,textarea,select,button,[contenteditable="true"]')))return;if(e.ctrlKey||e.altKey||e.metaKey)return;const now=performance.now();if(e.key==='Enter'){if(usbBuffer){e.preventDefault();processUsbBuffer()}return}if(typeof e.key!=='string'||e.key.length!==1)return;if(usbBuffer&&(now-usbLastAt)>USB_BURST_MAX_GAP)clearUsbBuffer();usbBuffer+=e.key;usbLastAt=now;if(usbTimer)clearTimeout(usbTimer);usbTimer=setTimeout(()=>{if(usbBuffer.length>=3)processUsbBuffer();else clearUsbBuffer()},USB_FLUSH_DELAY)}
document.addEventListener('keydown',captureUsbKey,true);
// Beberapa scanner USB tidak mengirim Enter/Tab. Field khusus USB tetap memproses
// nilai setelah burst input berhenti sejenak.
$('usb').addEventListener('input',()=>{const value=$('usb').value.trim();if(!value)return;if(usbTimer)clearTimeout(usbTimer);usbTimer=setTimeout(()=>{const code=$('usb').value.trim();if(code.length>=3){clearUsbBuffer();record(code,'usb')}},USB_FLUSH_DELAY)});
$('detectCamera').onclick=()=>window.PerpusScanner.detect();$('startCamera').onclick=()=>window.PerpusScanner.start(code=>record(code,'kamera'));$('stopCamera').onclick=()=>window.PerpusScanner.stop();window.PerpusScanner.loadDecoder();window.PerpusScanner.detect();
</script><?php require_once __DIR__.'/../layouts/footer.php'; ?>
